function nextCard(step=1){const a=activeList().slice(state.pack*30,state.pack*30+30);if(!a.length)return;state.card=(state.card+step+a.length)%a.length;state.flipped=false;renderStudy()}
function mark(type){const a=activeList().slice(state.pack*30,state.pack*30+30),w=a[state.card];if(!w)return;const old=progress[w.id]||{level:0};const level=type==='known'?Math.min(old.level+1,5):0;const interval=[1,1,3,7,16,35][level];progress[w.id]={level,due:nextDate(interval),last:today()};saveProgress();if(type==='known'){recordActivity();resolvedMistake(w);recordUnifiedHistory('Vocabulary','So‘z o‘rganildi',w.w,{wordId:w.id})}else addMistake(w);toast(type==='known'?'O‘rganildi! Keyinroq takrorlaysiz.':'Ertaga yana ko‘rib chiqasiz.');if(state.view==='review'||state.view==='mistakes')state.card=0;else state.card=(state.card+1)%a.length;state.flipped=false;renderStudy();updateNav()}
function pronounce(value){if(!('speechSynthesis' in window)){toast('Bu brauzerda ovozli talaffuz mavjud emas.');return}speechSynthesis.cancel();const utter=new SpeechSynthesisUtterance(value);utter.lang='en-GB';utter.rate=.84;const voices=speechSynthesis.getVoices();utter.voice=voices.find(v=>v.lang==='en-GB')||voices.find(v=>v.lang.startsWith('en'))||null;speechSynthesis.speak(utter)}
function speak(){const a=state.game&&state.game.mode==='flash'?state.game.items[state.game.idx]:state.view==='search'?searchResults()[state.searchCard]:activeList().slice(state.pack*30,state.pack*30+30)[state.card];if(a)pronounce(a.w)}
function scopeOptions(){return `<option value="all">Barcha so‘zlar (${fmt(words.length)})</option><option value="speaking">Speaking (${fmt(words.filter(w=>w.s).length)})</option>${topics.map((t,i)=>`<option value="topic:${i}">${esc(t)} (${fmt(words.filter(w=>w.t===t).length)})</option>`).join('')}`}
function gamePool(){if(state.scope==='speaking')return words.filter(w=>w.s);if(state.scope.startsWith('topic:'))return words.filter(w=>w.t===topics[Number(state.scope.split(':')[1])]);return words}
function studySection(){return state.view==='topics'?`topics:${state.topic}`:state.view==='custom'?`custom:${state.customPackId}`:state.view+':' }
function sessionKey(mode,kind='full',section='',packIndex=0,variant='game'){return kind==='pack'?`pack:${section}:${packIndex}:${mode==='mcq'?(variant==='study'?'packquiz':'quiz'):mode}`:`full:${mode}:${state.scope}`}
function saveGame(){const g=state.game;if(!g)return;if(g.mode==='typing'&&g.startedAt){g.elapsedMs+=Date.now()-g.startedAt;g.startedAt=0}sessions[g.key]={mode:g.mode,kind:g.kind,scope:g.scope,label:g.label,order:g.items.map(w=>w.id),idx:g.idx,correct:g.correct,batchStart:g.batchStart||0,batchEnds:g.batchEnds||[],matchedIds:[...g.matched],elapsedMs:g.elapsedMs||0,updatedAt:Date.now()};saveSessions()}
function pairOrder(items){const pending=shuffle(items),out=[],batchEnds=[];while(pending.length){const seen=new Set(),batch=[];for(let i=0;i<pending.length&&batch.length<6;){const k=norm(pending[i].u);if(seen.has(k)){i++;continue}seen.add(k);batch.push(pending.splice(i,1)[0])}out.push(...batch);batchEnds.push(out.length)}return {items:out,batchEnds}}
// Grammar extension begin
// Grammar laboratory: short patterns and newly authored examples.
const grammarModes=[
 ['flash','Flashcards','Qolipni oching, misol bilan mustahkamlang.','▣','g-purple'],
 ['meaning','Ma’noni tanlang','Strukturaga mos o‘zbekcha ma’noni toping.','☑','g-blue'],
 ['pairs','Juftliklarni toping','Qolipni aynan unga mos gap bilan bog‘lang.','⌘','g-green'],
 ['gap','Bo‘shliqni to‘ldiring','Namunadagi yetishmayotgan bo‘lakni yozing.','✎','g-orange'],
 ['sentence','Gapni tuzing','Bo‘laklarni tartiblash orqali gap yarating.','▤','g-pink'],
 ['detect','Structure Hunt','Qolip ishlatilgan gapni toping.','◎','g-violet'],
 ['rush','45 soniya','Tezkor raundlarda barcha strukturalarni aylaning.','ϟ','g-red']
];
function grammarSave(){try{localStorage.setItem(storageKey('vocab-atlas-grammar-progress-v1'),JSON.stringify(grammarProgress));localStorage.setItem(storageKey('vocab-atlas-grammar-sessions-v1'),JSON.stringify(grammarSessions));localStorage.setItem(storageKey('vocab-atlas-grammar-mistakes-v1'),JSON.stringify(grammarMistakes))}catch{}window.VocabCloud?.queue()}
function grammarAddMistake(id){const old=grammarMistakes[id]||{count:0,correct:0};grammarMistakes[id]={count:(old.count||0)+1,correct:0,last:today()};grammarSave();updateNav()}
function grammarResolveMistake(id){const item=grammarMistakes[id];if(!item)return;item.correct=(item.correct||0)+1;if(item.correct>=2)delete grammarMistakes[id];grammarSave();updateNav()}
function grammarLoad(){
 if(grammarBank||grammarLoading)return;
 grammarLoading=true;
 fetch('grammar-content.json').then(r=>{if(!r.ok)throw Error('Grammar yuklanmadi');return r.json()}).then(data=>{
  if(!Array.isArray(data.entries)||data.entries.length<100||!Array.isArray(data.sources))throw Error('Grammar formati noto‘g‘ri');
  grammarBank=data;grammarLoading=false;if(state.view==='grammar'||state.view==='grammargames'||state.view==='mistakes'&&state.mistakeTab==='grammar')render();
 }).catch(()=>{grammarLoading=false;if(['grammar','grammargames'].includes(state.view)||state.view==='mistakes'&&state.mistakeTab==='grammar')root.innerHTML=heading('Grammar structures','Ma’lumotlarni yuklab bo‘lmadi.')+'<button type="button" class="secondary-btn" data-action="grammar-retry">Qayta urinish</button>'});
}
function grammarPool(source=state.grammarSource){
 if(!grammarBank)return [];
 return grammarBank.entries.filter(e=>source==='all'||(source==='correction'?e.correction:e.sources.includes(source)));
}
function grammarSourceOptions(){
 if(!grammarBank)return '';
 const options=[['all','Barcha strukturalar'],...grammarBank.sources.map(s=>[s.id,s.name]),['correction','25 common mistakes']];
 return options.map(([id,name])=>'<option value="'+esc(id)+'" '+(state.grammarSource===id?'selected':'')+'>'+esc(name)+'</option>').join('');
}
function grammarSelected(){return grammarBank?.entries.find(e=>e.id===state.grammarFocus)||grammarBank?.entries[0]}
function grammarSourceChips(e){return e.sources.map(id=>'<span class="grammar-source">'+esc(grammarBank.sources.find(s=>s.id===id)?.name||id)+'</span>').join('')}

// Per-structure mastery lab: 5 exercise types x 10 = 50 tasks for every grammar structure.
const grammarDrillModes=[
 ['recognition','1. Tanib olish','Ma’no va to‘g‘ri misolni tez tanish','◎'],
 ['gap10','2. Bo‘shliqni to‘ldirish','Qolip bo‘lagini xotiradan yozish','✎'],
 ['build10','3. Gapni tuzish','So‘z tartibini 10 marta mustahkamlash','▤'],
 ['repair10','4. Xatoni tuzatish','Noto‘g‘ri bo‘lak o‘rniga to‘g‘risini tanlash','⚒'],
 ['production10','5. IELTS gap yozish','10 topic bo‘yicha o‘zingiz gap tuzish','★']
];
const grammarProductionTopics=['Education','Technology','Health','Environment','Work & Career','Travel','Family','Media','Culture','Society'];
const grammarGapFocus=['Qolipni xotiradan yozing.','Bu safar imloga ham e’tibor bering.','Qolipni tez va aniq yozing.','Gapdagi vazifasini o‘ylab yozing.','Connector / yordamchi so‘zni unutmay yozing.','Punktuatsiyani ko‘z oldingizga keltiring.','Qolipni aytib, keyin yozing.','Tarjimasini eslab, bo‘shliqni to‘ldiring.','IELTS javobida ishlatayotgandek yozing.','Oxirgi takror: yordamsiz yozing.'];
function grammarEnsureProgress(id){const p=grammarProgress[id]&&typeof grammarProgress[id]==='object'?grammarProgress[id]:(grammarProgress[id]={});if(!p.drills||typeof p.drills!=='object')p.drills={};return p}
function grammarDrillSlot(id,mode){const p=grammarEnsureProgress(id);if(!p.drills[mode]||typeof p.drills[mode]!=='object')p.drills[mode]={done:0,best:0,attempts:0,partialDone:0,partialCorrect:0};return p.drills[mode]}
function grammarDrillSummary(id){const p=grammarProgress[id]?.drills||{};let answered=0,best=0,completed=0;for(const [mode] of grammarDrillModes){const x=p[mode]||{};answered+=Math.min(10,Number(x.done)||Number(x.partialDone)||0);best+=Math.min(10,Number(x.best)||0);if(Number(x.done)>=10)completed++}return {answered,best,completed,mastered:completed===5&&best>=40,percent:Math.round(100*answered/50)}}
function grammarDrillModeMeta(mode){return grammarDrillModes.find(x=>x[0]===mode)||grammarDrillModes[0]}
function grammarDrillDistractors(e,i,count=3){const all=grammarBank.entries,base=Math.max(0,all.findIndex(x=>x.id===e.id)),out=[];for(let step=1;out.length<count&&step<all.length+10;step++){const x=all[(base+3+i*7+step*11)%all.length];if(x&&x.id!==e.id&&!out.some(y=>y.id===x.id))out.push(x)}return out}
function grammarDrillOptions(e,i){const opts=[e,...grammarDrillDistractors(e,i,3)],shift=i%opts.length;return opts.slice(shift).concat(opts.slice(0,shift))}
function grammarDrillTokens(e,i){const words=e.example.trim().split(/\s+/).map((word,n)=>({word,n}));if(words.length<2)return words;let out=words.slice(),seed=(i+3)*17+e.id.length*13;for(let n=out.length-1;n>0;n--){seed=(seed*9301+49297)%233280;const j=seed%(n+1);[out[n],out[j]]=[out[j],out[n]]}if(out.every((x,n)=>x.n===n))out.push(out.shift());return out}
function grammarSignalPhrases(e){const text=(' '+e.pattern.toLowerCase().replace(/[.…]+/g,' ')+' ').replace(/\s+/g,' ');const phrases=['not only','but also','so that','in spite of','rather than','even though','even if','as long as','as soon as','as if','as though','no sooner','hardly','scarcely','used to','would rather','whether or not','neither','nor','either','although','whereas','while','unless','despite','having','provided that','providing that','in case','because','since','what','whoever','whatever','whenever','wherever'];const found=phrases.filter(x=>text.includes(' '+x+' '));return found.slice(0,2)}
function grammarProductionCheck(text,e){const clean=norm(text),words=clean.split(/\s+/).filter(Boolean);if(words.length<5)return {ok:false,msg:'Kamida 5 ta so‘z bilan to‘liq gap yozing.'};const signals=grammarSignalPhrases(e);if(!signals.length)return {ok:true,msg:'Gap uzunligi yetarli. Endi ma’no va qolipni namuna bilan solishtiring.'};const hit=signals.some(x=>clean.includes(norm(x)));return {ok:hit,msg:hit?'Qolipning asosiy belgisi topildi. Endi ma’no va grammatikani namuna bilan solishtiring.':'Qolip belgisi topilmadi: '+signals.join(' / ')+' ni gapda ishlatib ko‘ring.'}}
function grammarDrillStart(mode){
 const e=grammarSelected();if(!e||!grammarDrillModes.some(x=>x[0]===mode))return;
 const slot=grammarDrillSlot(e.id,mode),resume=Number(slot.done)<10&&Number(slot.partialDone)>0&&Number(slot.partialDone)<10;
 state.grammarDrill={id:e.id,mode,idx:resume?Number(slot.partialDone):0,correct:resume?Number(slot.partialCorrect)||0:0,answered:false,lastCorrect:false,feedback:'',chosen:null,tokens:null,picked:[],response:'',finished:false};
 renderGrammarDrill();scrollPageTop();
}
function grammarDrillPersistPartial(){const d=state.grammarDrill;if(!d)return;const slot=grammarDrillSlot(d.id,d.mode);slot.partialDone=Math.max(Number(slot.partialDone)||0,d.idx+(d.answered?1:0));slot.partialCorrect=Math.max(0,d.correct);grammarSave()}
function grammarDrillAnswer(correct,feedback=''){
 const d=state.grammarDrill;if(!d||d.answered)return;d.answered=true;d.lastCorrect=!!correct;d.feedback=feedback;d.correct+=correct?1:0;
 if(correct)grammarResolveMistake(d.id);else grammarAddMistake(d.id);
 const slot=grammarDrillSlot(d.id,d.mode);slot.partialDone=d.idx+1;slot.partialCorrect=d.correct;grammarSave();renderGrammarDrill();
}
function grammarDrillFinish(){
 const d=state.grammarDrill;if(!d)return;const slot=grammarDrillSlot(d.id,d.mode);slot.done=10;slot.best=Math.max(Number(slot.best)||0,d.correct);slot.attempts=(Number(slot.attempts)||0)+1;slot.partialDone=0;slot.partialCorrect=0;slot.last=today();
 const p=grammarEnsureProgress(d.id),summary=grammarDrillSummary(d.id);p.known=summary.mastered;p.date=today();d.finished=true;grammarSave();recordActivity();const entry=grammarBank?.entries?.find(x=>x.id===d.id);recordUnifiedHistory('Grammar',`Grammar drill · ${entry?.pattern||d.id}`,`${grammarDrillModeMeta(d.mode)[1]} · ${d.correct}/10`,{score:d.correct,total:10});renderGrammarDrill();scrollPageTop();
}
function grammarDrillAdvance(){const d=state.grammarDrill;if(!d)return;if(d.idx>=9){grammarDrillFinish();return}d.idx++;d.answered=false;d.lastCorrect=false;d.feedback='';d.chosen=null;d.tokens=null;d.picked=[];d.response='';grammarDrillPersistPartial();renderGrammarDrill()}
function grammarDrillFeedback(d,e){if(!d.answered)return '';const extra=d.mode==='production10'?'<div class="grammar-drill-reference"><small>REFERENCE EXAMPLE</small><p>'+esc(e.example)+'</p></div>':'';return '<div class="grammar-drill-feedback '+(d.lastCorrect?'good':'bad')+'"><strong>'+(d.lastCorrect?'✓ To‘g‘ri / qabul qilindi':'✕ Yana bir marta ko‘rib chiqing')+'</strong><p>'+esc(d.feedback)+'</p></div>'+extra+'<div class="center-actions"><button type="button" class="primary-btn" data-action="grammar-drill-next">'+(d.idx===9?'Natijani ko‘rish':'Keyingi →')+'</button></div>'}
function renderGrammarDrill(){
 const d=state.grammarDrill;if(!d){renderGrammarLibrary();return}const e=grammarBank?.entries.find(x=>x.id===d.id);if(!e){state.grammarDrill=null;renderGrammarLibrary();return}
 const meta=grammarDrillModeMeta(d.mode),slot=grammarDrillSlot(e.id,d.mode),summary=grammarDrillSummary(e.id);
 if(d.finished){const strong=d.correct>=8;root.innerHTML=heading(e.pattern,meta[1]+' · 10 ta mashq tugadi')+'<section class="panel grammar-drill-result"><div class="grammar-drill-score '+(strong?'strong':'weak')+'"><small>BU URINISH</small><strong>'+d.correct+' / 10</strong><span>'+(strong?'Juda yaxshi — bu bosqich mustahkam.':'8/10 ga yetkazish uchun yana bir raund foydali.')+'</span></div><div class="grammar-mastery-mini"><b>50 talik umumiy progress</b><span>'+summary.answered+' / 50 · eng yaxshi natijalar '+summary.best+' / 50</span></div><div class="center-actions"><button type="button" class="secondary-btn" data-action="grammar-drill-back">← 5 mashqqa qaytish</button><button type="button" class="primary-btn" data-action="grammar-drill-retry">Yana 10 ta →</button></div></section>';return}
 let body='';
 if(d.mode==='recognition'){
  const opts=grammarDrillOptions(e,d.idx),meaningRound=d.idx%2===0;
  body='<p class="grammar-drill-kicker">'+(meaningRound?'Strukturaning vazifasini tanlang':'Shu structure ishlatilgan gapni toping')+'</p><h2 class="grammar-drill-target">'+esc(e.pattern)+'</h2><div class="grammar-drill-choices">'+opts.map(x=>'<button type="button" class="grammar-drill-choice '+(d.answered?(x.id===e.id?'right':x.id===d.chosen?'wrong':''):'')+'" data-action="grammar-drill-choice" data-id="'+esc(x.id)+'" '+(d.answered?'disabled':'')+'>'+esc(meaningRound?x.meaning:x.example)+'</button>').join('')+'</div>';
 }else if(d.mode==='gap10'){
  body='<p class="grammar-drill-kicker">'+esc(grammarGapFocus[d.idx])+'</p><h2 class="grammar-drill-sentence">'+esc(e.gap)+'</h2><p class="grammar-meaning-hint">'+esc(e.meaning)+'</p><input id="grammarDrillInput" class="game-input" type="text" autocomplete="off" spellcheck="false" placeholder="Yetishmayotgan bo‘lakni yozing" '+(d.answered?'disabled':'')+'><div class="center-actions">'+(d.answered?'':'<button type="button" class="primary-btn" data-action="grammar-drill-check-gap">Tekshirish</button>')+'</div>';
 }else if(d.mode==='build10'){
  if(!d.tokens){d.tokens=grammarDrillTokens(e,d.idx);d.picked=[]}
  body='<p class="grammar-drill-kicker">So‘zlarni to‘g‘ri tartibda tering</p><p class="grammar-meaning-hint">'+esc(e.meaning)+'</p><div class="grammar-drill-answer-zone">'+(d.picked.length?d.picked.map((x,i)=>'<button type="button" class="token" data-action="grammar-drill-untoken" data-index="'+i+'" '+(d.answered?'disabled':'')+'>'+esc(x.word)+'</button>').join(''):'Bu yerga so‘zlarni joylang')+'</div><div class="sentence-tokens">'+d.tokens.map((x,i)=>'<button type="button" class="token" data-action="grammar-drill-token" data-index="'+i+'" '+(d.answered?'disabled':'')+'>'+esc(x.word)+'</button>').join('')+'</div><div class="center-actions">'+(d.answered?'':'<button type="button" class="primary-btn" data-action="grammar-drill-check-build">Tekshirish</button>')+'</div>';
 }else if(d.mode==='repair10'){
  const opts=grammarDrillOptions(e,d.idx),wrong=grammarDrillDistractors(e,d.idx,1)[0],wrongChunk=wrong?.chunk||wrong?.pattern||'???',bad=e.gap.includes('_____')?e.gap.replace('_____',wrongChunk):e.example;
  body='<p class="grammar-drill-kicker">Xato bo‘lakni to‘g‘ri variant bilan almashtiring</p><h2 class="grammar-drill-sentence grammar-drill-bad">'+esc(bad)+'</h2><div class="grammar-drill-choices compact">'+opts.map(x=>'<button type="button" class="grammar-drill-choice '+(d.answered?(x.id===e.id?'right':x.id===d.chosen?'wrong':''):'')+'" data-action="grammar-drill-choice" data-id="'+esc(x.id)+'" '+(d.answered?'disabled':'')+'>'+esc(x.chunk||x.pattern)+'</button>').join('')+'</div>';
 }else{
  const topic=grammarProductionTopics[d.idx];
  body='<p class="grammar-drill-kicker">'+esc(topic)+' · o‘zingiz 1 ta IELTS gapi yozing</p><h2 class="grammar-drill-target">'+esc(e.pattern)+'</h2><p class="grammar-meaning-hint">'+esc(e.meaning)+'</p><textarea id="grammarDrillProduction" class="grammar-drill-textarea" rows="4" maxlength="500" placeholder="'+esc(topic)+' haqida shu structure bilan tabiiy gap yozing..." '+(d.answered?'disabled':'')+'>'+esc(d.response||'')+'</textarea><p class="note">Avto-check faqat qolipning asosiy belgilarini tekshiradi; to‘liq IELTS grammatik bahosi emas.</p><div class="center-actions">'+(d.answered?'':'<button type="button" class="primary-btn" data-action="grammar-drill-check-production">Gapni tekshirish</button>')+'</div>';
 }
 root.innerHTML=heading(e.pattern,'Har bir structure uchun 5 xil mashq × 10 ta = 50 ta mustahkamlash.')+'<div class="grammar-drill-top"><button type="button" class="page-back" data-action="grammar-drill-back">← Structurega qaytish</button><div><strong>'+esc(meta[3]+' '+meta[1])+'</strong><small>'+(d.idx+1)+' / 10 · shu urinish '+d.correct+' to‘g‘ri</small></div><span>'+summary.answered+' / 50</span></div><div class="grammar-drill-progress"><span style="width:'+((d.idx+(d.answered?1:0))*10)+'%"></span></div><section class="panel grammar-drill-stage">'+body+grammarDrillFeedback(d,e)+'</section>';
}
function grammarMasteryPanel(e){
 const sum=grammarDrillSummary(e.id);return '<section class="grammar-mastery"><div class="grammar-mastery-head"><div><small>MASTERY LAB</small><h3>50 ta mustahkamlash mashqi</h3><p>5 xil mashq · har birida 10 tadan. 40/50+ va barcha 5 bosqich tugasa structure “Mustahkamlandi” bo‘ladi.</p></div><div class="grammar-mastery-score '+(sum.mastered?'done':'')+'"><strong>'+sum.answered+'/50</strong><span>'+(sum.mastered?'✓ Mustahkamlandi':'Best '+sum.best+'/50')+'</span></div></div><div class="grammar-mastery-progress"><span style="width:'+sum.percent+'%"></span></div><div class="grammar-drill-grid">'+grammarDrillModes.map(([mode,title,desc,icon])=>{const x=grammarProgress[e.id]?.drills?.[mode]||{},done=Number(x.done)>=10,best=Number(x.best)||0,partial=Number(x.partialDone)||0;return '<button type="button" class="grammar-drill-card '+(done&&best>=8?'done':'')+'" data-action="grammar-drill-start" data-mode="'+mode+'"><span class="grammar-drill-icon">'+icon+'</span><div><strong>'+esc(title)+'</strong><small>'+esc(desc)+'</small><em>'+(done?'Best '+best+'/10':partial?'Davom etish '+partial+'/10':'Boshlash · 0/10')+'</em></div><b>→</b></button>'}).join('')+'</div></section>'}
function renderGrammarLibrary(){
 if(state.grammarDrill){renderGrammarDrill();return}
 if(!grammarBank){root.innerHTML=heading('Grammar structures','Strukturalar yuklanmoqda…')+'<div class="loading"><span class="spinner"></span> Yuklanmoqda…</div>';grammarLoad();return}
 const pool=grammarPool(),q=norm(state.grammarQuery),list=pool.filter(e=>!q||norm(e.pattern+' '+e.meaning+' '+e.example).includes(q));
 if(list.length&&!list.some(e=>e.id===state.grammarFocus)){state.grammarFocus=list[0].id;state.grammarFlipped=false}
 const pages=Math.max(1,Math.ceil(list.length/18));state.grammarPage=Math.max(0,Math.min(pages-1,state.grammarPage));
 const page=list.slice(state.grammarPage*18,state.grammarPage*18+18),e=list.find(x=>x.id===state.grammarFocus),known=grammarBank.entries.filter(x=>grammarDrillSummary(x.id).mastered).length,idx=e?list.indexOf(e):-1;
 let html=heading('Grammar structures','Har bir structure: ma’no + misol + 5 xil mashq × 10 ta = 50 ta mustahkamlash.',grammarBank.entries.length+' ta structure · '+(grammarBank.entries.length*50)+' ta mashq');
 html+='<div class="page-back-row"><button type="button" class="page-back" data-action="back-one">← Ortga</button><span class="speaking-count">'+known+' / '+grammarBank.entries.length+' ta o‘rganilgan</span></div>';
 html+='<div class="grammar-toolbar"><label for="grammarSource">Manba</label><select id="grammarSource">'+grammarSourceOptions()+'</select><label for="grammarSearch">Qidirish</label><input id="grammarSearch" type="search" autocomplete="off" value="'+esc(state.grammarQuery)+'" placeholder="Qolip, ma’no yoki misol..."><button type="button" class="primary-btn" data-action="grammar-games">7 ta o‘yin →</button></div>';
 html+='<div class="grammar-layout"><section class="panel grammar-index"><div class="section-heading"><h2>Strukturalar</h2><small>'+list.length+' ta</small></div><div class="grammar-list">'+(page.length?page.map((x,i)=>'<button type="button" class="grammar-list-item '+(x.id===e?.id?'active':'')+'" data-action="grammar-select" data-id="'+esc(x.id)+'"><small>'+(state.grammarPage*18+i+1)+' · '+(x.correction?'Xatoni tuzatish':'Grammar')+'</small><strong>'+esc(x.pattern)+'</strong></button>').join(''):'<p class="note">Qidiruv natijasi topilmadi.</p>')+'</div><div class="pager"><button type="button" data-action="grammar-page-prev" '+(state.grammarPage===0?'disabled':'')+'>←</button><span>'+(state.grammarPage+1)+' / '+pages+'</span><button type="button" data-action="grammar-page-next" '+(state.grammarPage===pages-1?'disabled':'')+'>→</button></div></section>';
 if(e){
  html+='<section class="panel grammar-detail"><div class="grammar-chips">'+grammarSourceChips(e)+'</div><div class="grammar-card"><div class="grammar-card-label">STRUCTURE '+(idx+1)+' / '+list.length+'</div><h2>'+esc(e.pattern)+'</h2>';
  if(state.grammarFlipped)html+='<div class="grammar-answer"><span>O‘ZBEKCHA MA’NO</span><p>'+esc(e.meaning)+'</p><span>YANGI MISOL</span><blockquote>'+esc(e.example)+'</blockquote><button type="button" class="speaking-card-audio" data-action="grammar-speak">🔊 Misolni eshitish</button></div>';
  else html+='<p class="grammar-card-hint">Qolip qaysi vaziyatda ishlatilishini o‘ylang, so‘ng kartani aylantiring.</p>';
  html+='<button type="button" class="speaking-sample-toggle" data-action="grammar-flip">'+(state.grammarFlipped?'Qolipga qaytish ↑':'Ma’no va misolni ochish ↓')+'</button></div>';
  if(e.id==='nominalisation')html+='<div class="grammar-forms"><h3>Nominalisation: 28 ta so‘z shakli</h3><div>'+grammarBank.nominalForms.map(([from,to])=>'<span><b>'+esc(from)+'</b> → '+esc(to)+'</span>').join('')+'</div><small>Manbadagi “advanced → advancement” juftligi “advance → advancement” tarzida tuzatildi.</small></div>';
  html+=grammarMasteryPanel(e);
  html+='<div class="grammar-actions"><button type="button" class="secondary-btn" data-action="grammar-prev" '+(idx===0?'disabled':'')+'>← Oldingi</button><span class="grammar-mastery-status '+(grammarDrillSummary(e.id).mastered?'done':'')+'">'+(grammarDrillSummary(e.id).mastered?'✓ Mustahkamlandi':'50 ta mashqni bajaring')+'</span><button type="button" class="secondary-btn" data-action="grammar-next" '+(idx===list.length-1?'disabled':'')+'>Keyingi →</button></div><p class="note">“Yodladim” o‘rniga endi amaliy mastery tizimi ishlaydi. Har structure 50 ta mashq bilan mustahkamlanadi.</p></section>';
 }else html+='<section class="panel grammar-detail"><p class="note">Boshqa so‘z yoki manbani sinab ko‘ring.</p></section>';
 root.innerHTML=html+'</div>';
}
function grammarSelectRelative(delta){
 const q=norm(state.grammarQuery),list=grammarPool().filter(e=>!q||norm(e.pattern+' '+e.meaning+' '+e.example).includes(q));
 const n=list.findIndex(e=>e.id===state.grammarFocus)+delta;
 if(n>=0&&n<list.length){state.grammarFocus=list[n].id;state.grammarPage=Math.floor(n/18);state.grammarFlipped=false;state.grammarDrill=null;renderGrammarLibrary()}
}
function grammarSessionKey(mode,source=state.grammarSource){return mode+'|'+source}
function grammarCurrent(){return state.grammarGame?.items[state.grammarGame.idx]}
function grammarSaveSession(){
 const g=state.grammarGame;if(!g)return;
 grammarSessions[g.key]={order:g.items.map(e=>e.id),idx:g.idx,correct:g.correct,matched:[...g.matched]};
 grammarSave();
}
function renderGrammarGames(){
 if(!grammarBank){root.innerHTML=heading('Grammar o‘yinlari','Ma’lumotlar yuklanmoqda…')+'<div class="loading"><span class="spinner"></span> Yuklanmoqda…</div>';grammarLoad();return}
 if(state.grammarGame){renderGrammarGame();return}
 if(state.grammarResult){
  const r=state.grammarResult;
  root.innerHTML=heading('Grammar raundi tugadi','O‘rganish davom etadi.')+'<section class="panel score-hero"><div class="trophy">✧</div><h2>'+r.correct+' / '+r.total+'</h2><p>'+esc(r.title)+' · '+r.total+' ta struktura</p><div class="center-actions"><button type="button" class="primary-btn" data-action="grammar-result-back">← O‘yinlar</button><button type="button" class="secondary-btn" data-action="grammar-result-learn">Kartalarni ko‘rish</button></div></section>';return
 }
 const pool=grammarPool();
 let html='<div class="page-back-row"><button type="button" class="page-back" data-action="back-one">← Ortga</button><button type="button" class="page-close" data-action="back-one">✕ Chiqish</button></div>';
 html+=heading('Grammar o‘yinlari','Har bir o‘yin tanlangan manbadagi barcha '+pool.length+' ta struktura bo‘ylab yuradi; jarayon saqlanadi.','7 xil o‘yin');
 html+='<div class="games-toolbar"><label for="grammarGameScope">Qaysi strukturalar?</label><select id="grammarGameScope">'+grammarSourceOptions()+'</select><span>Juftliklar 6 tadan, tezkor o‘yin 45 soniyalik raundlarda davom etadi.</span></div><div class="games-grid">';
 html+=grammarModes.map(m=>{const s=grammarSessions[grammarSessionKey(m[0])];return '<button type="button" class="game-tile '+m[4]+'" data-action="grammar-start" data-mode="'+m[0]+'"><span class="game-icon" aria-hidden="true">'+m[3]+'</span><strong>'+m[1]+'</strong><small>'+m[2]+'</small><span class="game-count">'+(s?'Davom ettirish: '+s.idx+' / '+s.order.length:pool.length+' ta struktura')+'</span></button>'}).join('')+'</div>';
 root.innerHTML=html;
}
function grammarStart(mode){
 if(!grammarModes.some(m=>m[0]===mode))return;
 const pool=grammarPool();if(!pool.length){toast('Bu manbada struktura topilmadi.');return}
 const key=grammarSessionKey(mode),saved=grammarSessions[key],valid=saved&&saved.order.length===pool.length&&saved.order.every(id=>pool.some(e=>e.id===id));
 const items=valid?saved.order.map(id=>grammarBank.entries.find(e=>e.id===id)):shuffle(pool);
 pushPage('grammargame');
 state.grammarResult=null;state.grammarGame={mode,key,items,idx:valid?Math.min(saved.idx,items.length-1):0,correct:valid?saved.correct:0,matched:new Set(valid?saved.matched:[]),selected:null,options:null,answered:false,feedback:'',flipped:false,tokenIndex:-1,tokens:[],picked:[],batchStart:-1,timeLeft:45,paused:false};
 grammarSaveSession();if(mode==='rush')grammarStartTimer();renderGrammarGame();scrollPageTop();
}
function grammarStartTimer(){
 clearInterval(state.grammarTimer);
 const g=state.grammarGame;if(!g||g.mode!=='rush')return;
 g.paused=false;g.timeLeft=45;const end=Date.now()+45000;
 state.grammarTimer=setInterval(()=>{if(state.grammarGame!==g){clearInterval(state.grammarTimer);return}g.timeLeft=Math.max(0,Math.ceil((end-Date.now())/1000));const el=$('#grammarClock');if(el)el.textContent=g.timeLeft+' s';if(!g.timeLeft){clearInterval(state.grammarTimer);state.grammarTimer=null;g.paused=true;grammarSaveSession();renderGrammarGame()}},250);
}
function grammarOptions(g){
 if(g.options)return g.options;
 const answer=grammarCurrent(),others=pick(g.items.filter(x=>x.id!==answer.id),3);
 g.options=shuffle([answer,...others]);return g.options;
}
function grammarGameBar(g){return '<div class="game-top"><button type="button" class="secondary-btn" data-action="grammar-exit">← O‘yinlarga qaytish</button><strong>'+esc(grammarModes.find(m=>m[0]===g.mode)?.[1]||'Mashq')+'</strong><small>'+(g.idx+1)+' / '+g.items.length+'</small></div><div class="game-progress"><span style="width:'+(100*g.idx/g.items.length)+'%"></span></div>'}
function grammarAnswerPanel(g){return g.answered?'<div class="grammar-feedback '+(g.lastCorrect?'good':'bad')+'">'+(g.lastCorrect?'To‘g‘ri!':'To‘g‘ri javob: '+esc(g.feedback))+'</div><div class="center-actions"><button type="button" class="primary-btn" data-action="grammar-advance">Keyingi →</button></div>':''}
function renderGrammarGame(){
 const g=state.grammarGame;if(!g)return;
 const e=grammarCurrent(),mode=g.mode;
 if(mode==='rush'&&g.paused){root.innerHTML=heading('45 soniya','Qolgan kartalar keyingi raundda davom etadi.')+'<section class="game-stage">'+grammarGameBar(g)+'<div class="score-hero"><h2>'+g.idx+' / '+g.items.length+'</h2><p>Shu joyingiz saqlandi.</p><button type="button" class="primary-btn" data-action="grammar-resume">Keyingi 45 soniya →</button></div></section>';return}
 let html=heading('Grammar o‘yini','Har bir struktura shu o‘yinda bir marta ko‘rinadi.')+'<section class="game-stage grammar-game">'+grammarGameBar(g);
 if(mode==='flash'){
  html+='<button type="button" class="grammar-game-flash '+(g.flipped?'revealed':'')+'" data-action="grammar-game-flip"><small>FLASHCARD · '+(g.idx+1)+' / '+g.items.length+'</small><strong>'+esc(g.flipped?e.meaning:e.pattern)+'</strong><span>'+esc(g.flipped?e.example:'Ma’no va misolni ochish uchun bosing')+'</span></button><div class="center-actions"><button type="button" class="secondary-btn" data-action="grammar-grade" data-status="learning">Yana mashq qilaman</button><button type="button" class="primary-btn" data-action="grammar-grade" data-status="known">Yodladim ✓</button></div>';
 }else if(mode==='pairs'){
  const start=Math.floor(g.idx/6)*6,batch=g.items.slice(start,start+6);
  if(g.batchStart!==start){g.batchStart=start;g.left=shuffle(batch);g.right=shuffle(batch);g.selected=null}
  html+='<p class="quiz-prompt">Qolipni unga mos yangi misol bilan juftlang · '+(start+1)+'–'+(start+batch.length)+'</p><div class="pair-grid"><div class="pair-col">'+g.left.map(x=>'<button type="button" class="pair '+(g.matched.has(x.id)?'matched':'')+' '+(g.selected?.id===x.id&&g.selected.side==='left'?'selected':'')+'" '+(g.matched.has(x.id)?'disabled':'')+' data-action="grammar-pair" data-side="left" data-id="'+esc(x.id)+'">'+esc(x.pattern)+'</button>').join('')+'</div><div class="pair-col">'+g.right.map(x=>'<button type="button" class="pair '+(g.matched.has(x.id)?'matched':'')+' '+(g.selected?.id===x.id&&g.selected.side==='right'?'selected':'')+'" '+(g.matched.has(x.id)?'disabled':'')+' data-action="grammar-pair" data-side="right" data-id="'+esc(x.id)+'">'+esc(x.example)+'</button>').join('')+'</div></div>';
 }else if(mode==='gap'){
  html+='<p class="quiz-prompt">Yetishmayotgan bo‘lakni yozing · '+esc(e.pattern)+'</p><h2 class="quiz-word">'+esc(e.gap)+'</h2><p class="grammar-meaning-hint">'+esc(e.meaning)+'</p><input id="grammarGameInput" class="game-input" type="text" autocomplete="off" spellcheck="false" placeholder="Inglizcha bo‘lak" aria-label="Yetishmayotgan bo‘lak" '+(g.answered?'disabled':'')+'><div class="center-actions">'+(g.answered?'':'<button type="button" class="primary-btn" data-action="grammar-check-gap">Tekshirish</button>')+'</div>'+grammarAnswerPanel(g);
 }else if(mode==='sentence'){
  if(g.tokenIndex!==g.idx){g.tokenIndex=g.idx;g.tokens=shuffle(e.example.trim().split(/\s+/).map((word,i)=>({word,i})));g.picked=[]}
  html+='<p class="quiz-prompt">Qolip: '+esc(e.pattern)+'</p><p class="grammar-meaning-hint">'+esc(e.meaning)+'</p><div class="answer-zone">'+(g.picked.length?g.picked.map((x,i)=>'<button type="button" class="token" data-action="grammar-untoken" data-index="'+i+'">'+esc(x.word)+'</button>').join(''):'So‘zlarni tanlab gapni tuzing')+'</div><div class="sentence-tokens">'+g.tokens.map((x,i)=>'<button type="button" class="token" data-action="grammar-token" data-index="'+i+'">'+esc(x.word)+'</button>').join('')+'</div><div class="center-actions">'+(g.answered?'':'<button type="button" class="primary-btn" data-action="grammar-check-sentence">Tekshirish</button>')+'</div>'+grammarAnswerPanel(g);
 }else{
  const options=grammarOptions(g),prompt=mode==='meaning'?e.pattern:mode==='detect'?e.pattern:e.meaning,lead=mode==='meaning'?'Ma’nosini tanlang':mode==='detect'?'Shu qolip ishlatilgan gapni toping':'45 soniya · mos strukturani toping';
  html+='<p class="quiz-prompt">'+lead+'</p><h2 class="quiz-word">'+esc(prompt)+'</h2>'+(mode==='rush'?'<div class="grammar-clock">⏱ <strong id="grammarClock">'+g.timeLeft+' s</strong></div>':'')+'<div class="choices">'+options.map(x=>'<button type="button" class="choice '+(g.answered?(x.id===e.id?'right':x.id===g.chosen?'wrong':''):'')+'" data-action="grammar-choice" data-id="'+esc(x.id)+'" '+(g.answered?'disabled':'')+'>'+esc(mode==='meaning'?x.meaning:mode==='detect'?x.example:x.pattern)+'</button>').join('')+'</div>'+grammarAnswerPanel(g);
 }
 root.innerHTML=html+'</section>';
}
function grammarGrade(correct,feedback=''){
 const g=state.grammarGame;if(!g||g.answered)return;
 g.answered=true;g.lastCorrect=correct;g.feedback=feedback;g.correct+=correct?1:0;
 if(correct){grammarProgress[grammarCurrent().id]={known:true,date:today()};recordActivity();grammarResolveMistake(grammarCurrent().id)}
 else{grammarAddMistake(grammarCurrent().id);if(g.mode==='flash')grammarProgress[grammarCurrent().id]={known:false,date:today()}}
 grammarSave();grammarSaveSession();
 if(g.mode==='flash'){grammarAdvance();return}
 if(g.mode==='rush'){if(!correct)toast('Javob: '+feedback);grammarAdvance();return}
 renderGrammarGame();
}
function grammarAdvance(){
 const g=state.grammarGame;if(!g)return;
 g.idx++;g.options=null;g.answered=false;g.feedback='';g.flipped=false;g.chosen=null;
 if(g.idx>=g.items.length){grammarFinish();return}
 grammarSaveSession();renderGrammarGame();
}
function grammarFinish(){
 const g=state.grammarGame;if(!g)return;
 clearInterval(state.grammarTimer);state.grammarTimer=null;
 delete grammarSessions[g.key];grammarSave();
 state.grammarResult={correct:g.correct,total:g.items.length,title:grammarModes.find(m=>m[0]===g.mode)?.[1]||'O‘yin'};
 recordUnifiedHistory('Grammar',`Grammar o‘yini · ${state.grammarResult.title}`,`${g.correct}/${g.items.length} to‘g‘ri`,{score:g.correct,total:g.items.length});
 state.grammarGame=null;renderGrammarGames();scrollPageTop();
}
function grammarExit(){
 if(state.grammarGame)grammarSaveSession();
 clearInterval(state.grammarTimer);state.grammarTimer=null;
 state.grammarGame=null;state.grammarResult=null;backSteps(1);
}
function grammarHandleAction(a,b){
 const g=state.grammarGame,d=state.grammarDrill;
 if(a==='grammar-retry'){grammarLoad();return true}
 if(a==='grammar-drill-start'){grammarDrillStart(b.dataset.mode);return true}
 if(a==='grammar-drill-back'){grammarDrillPersistPartial();state.grammarDrill=null;renderGrammarLibrary();scrollPageTop();return true}
 if(a==='grammar-drill-retry'){const mode=d?.mode;if(!mode)return true;state.grammarDrill=null;grammarDrillStart(mode);return true}
 if(a==='grammar-drill-next'){if(d?.answered)grammarDrillAdvance();return true}
 if(a==='grammar-drill-choice'){if(!d||d.answered||!['recognition','repair10'].includes(d.mode))return true;const e=grammarBank?.entries.find(x=>x.id===d.id),id=b.dataset.id;if(!e)return true;d.chosen=id;const correct=id===e.id;grammarDrillAnswer(correct,d.mode==='recognition'?(d.idx%2===0?e.meaning:e.example):(e.chunk||e.pattern));return true}
 if(a==='grammar-drill-check-gap'){if(!d||d.mode!=='gap10'||d.answered)return true;const e=grammarBank?.entries.find(x=>x.id===d.id),value=$('#grammarDrillInput')?.value.trim()||'';if(!value){toast('Avval bo‘shliqni to‘ldiring.');return true}grammarDrillAnswer(norm(value)===norm(e.chunk),e.chunk);return true}
 if(a==='grammar-drill-token'||a==='grammar-drill-untoken'){if(!d||d.mode!=='build10'||d.answered)return true;const from=a==='grammar-drill-token'?d.tokens:d.picked,to=a==='grammar-drill-token'?d.picked:d.tokens,n=Number(b.dataset.index);if(n>=0&&n<from.length){to.push(from.splice(n,1)[0]);renderGrammarDrill()}return true}
 if(a==='grammar-drill-check-build'){if(!d||d.mode!=='build10'||d.answered)return true;const e=grammarBank?.entries.find(x=>x.id===d.id);if(!d.picked.length){toast('Avval gapni tuzing.');return true}grammarDrillAnswer(norm(d.picked.map(x=>x.word).join(' '))===norm(e.example),e.example);return true}
 if(a==='grammar-drill-check-production'){if(!d||d.mode!=='production10'||d.answered)return true;const e=grammarBank?.entries.find(x=>x.id===d.id),value=$('#grammarDrillProduction')?.value.trim()||'',check=grammarProductionCheck(value,e);if(!check.ok){toast(check.msg);return true}d.response=value;grammarDrillAnswer(true,check.msg);return true}
 if(a==='grammar-games'){view('grammargames');return true}
 if(a==='grammar-select'){
  if(grammarBank?.entries.some(x=>x.id===b.dataset.id)&&state.grammarFocus!==b.dataset.id){pushPage('grammar');state.grammarFocus=b.dataset.id;state.grammarFlipped=false;state.grammarDrill=null;renderGrammarLibrary()}return true
 }
 if(a==='grammar-page-prev'||a==='grammar-page-next'){state.grammarPage+=a==='grammar-page-next'?1:-1;renderGrammarLibrary();return true}
 if(a==='grammar-flip'){state.grammarFlipped=!state.grammarFlipped;renderGrammarLibrary();return true}
 if(a==='grammar-mark'){
  const id=state.grammarFocus;
  if(grammarBank?.entries.some(x=>x.id===id)){grammarProgress[id]={known:b.dataset.status==='known',date:today()};grammarSave();recordActivity();renderGrammarLibrary()}return true
 }
 if(a==='grammar-prev'||a==='grammar-next'){grammarSelectRelative(a==='grammar-prev'?-1:1);return true}
 if(a==='grammar-speak'){const e=grammarSelected();if(e)pronounce(e.example);return true}
 if(a==='grammar-start'){grammarStart(b.dataset.mode);return true}
 if(a==='grammar-exit'){grammarExit();return true}
 if(a==='grammar-result-back'){state.grammarResult=null;backSteps(1);return true}
 if(a==='grammar-result-learn'){state.grammarResult=null;view('grammar');return true}
 if(a==='grammar-resume'){grammarStartTimer();renderGrammarGame();return true}
 if(!g)return false;
 if(a==='grammar-game-flip'){g.flipped=!g.flipped;renderGrammarGame();return true}
 if(a==='grammar-grade'){grammarGrade(b.dataset.status==='known');return true}
 if(a==='grammar-advance'){grammarAdvance();return true}
 if(a==='grammar-choice'){
  if(g.answered||g.paused)return true;
  const id=b.dataset.id,e=grammarCurrent();
  if(!g.options?.some(x=>x.id===id))return true;
  g.chosen=id;
  grammarGrade(id===e.id,g.mode==='meaning'?e.meaning:g.mode==='detect'?e.example:e.pattern);
  return true
 }
 if(a==='grammar-pair'){
  const id=b.dataset.id,side=b.dataset.side;
  if(g.mode!=='pairs'||g.matched.has(id)||!['left','right'].includes(side)||![...g.left,...g.right].some(x=>x.id===id))return true;
  if(!g.selected||g.selected.side===side){g.selected={id,side};renderGrammarGame();return true}
  if(g.selected.id===id){g.matched.add(id);g.correct++;g.idx++;grammarProgress[id]={known:true,date:today()};recordActivity();grammarResolveMistake(id);g.selected=null;if(g.idx>=g.items.length)grammarFinish();else{grammarSaveSession();renderGrammarGame()}}
  else{grammarAddMistake(g.selected.id);grammarAddMistake(id);g.selected=null;toast('Bu juftlik mos kelmadi.');renderGrammarGame()}
  return true
 }
 if(a==='grammar-check-gap'){
  if(g.mode!=='gap'||g.answered)return true;
  const value=$('#grammarGameInput')?.value.trim()||'';if(!value){toast('Avval bo‘shliqni to‘ldiring.');return true}
  grammarGrade(norm(value)===norm(grammarCurrent().chunk),grammarCurrent().chunk);return true
 }
 if(a==='grammar-token'||a==='grammar-untoken'){
  if(g.mode!=='sentence'||g.answered)return true;
  const from=a==='grammar-token'?g.tokens:g.picked,to=a==='grammar-token'?g.picked:g.tokens,n=Number(b.dataset.index);
  if(n>=0&&n<from.length){to.push(from.splice(n,1)[0]);renderGrammarGame()}return true
 }
 if(a==='grammar-check-sentence'){
  if(g.mode!=='sentence'||g.answered)return true;
  if(!g.picked.length){toast('Avval gapni tuzing.');return true}
  grammarGrade(norm(g.picked.map(x=>x.word).join(' '))===norm(grammarCurrent().example),grammarCurrent().example);return true
 }
 return false
}
// Grammar extension end
// Speaking Mock extension begin
// Speaking Mock: one Part 1 topic, one Part 2 cue card and related Part 3.
const mockDraftKey='vocab-atlas-mock-draft-v2';

function mockPersist(){
 const s=state.mockSession;if(!s)return;
 try{localStorage.setItem(storageKey(mockDraftKey),JSON.stringify({savedAt:Date.now(),questions:s.questions,answers:s.answers.map(x=>({text:x.text,audioPath:x.audioPath||null,transcript:x.transcript||''})),current:s.current,topics:s.topics}))}catch{}
 window.VocabCloud?.queue();
}
function mockRestore(){
 if(state.mockSession)return;
 const d=load(mockDraftKey,null);
 if(!d||!Number.isFinite(d.savedAt)||(!window.VocabCloud?.enabled&&Date.now()-d.savedAt>7*86400000)||!Array.isArray(d.questions)||!Array.isArray(d.answers)||d.questions.length<7||d.questions.length>9||d.questions.length!==d.answers.length||!d.questions.every(x=>[1,2,3].includes(x?.part)&&typeof x.q==='string'&&typeof x.topic==='string')||!d.answers.every(x=>typeof x==='string'||x&&typeof x.text==='string')||!d.topics)return;
 state.mockSession={questions:d.questions,answers:d.answers.map(x=>({text:(typeof x==='string'?x:x.text).slice(0,4000),audioPath:typeof x==='object'&&typeof x.audioPath==='string'?x.audioPath:null,transcript:typeof x==='object'&&typeof x.transcript==='string'?x.transcript:'',blob:null,url:null,mime:''})),current:Math.max(0,Math.min(d.questions.length-1,Number(d.current)||0)),topics:d.topics};
}

function mockNew(){
 if(!speakingBank)return;
 const old=state.mockSession;
 if(old)for(const answer of old.answers)if(answer.url)URL.revokeObjectURL(answer.url);
 const p1=pick(speakingBank.part1.filter(g=>g.questions.length>=3),1)[0];
 const p2Index=Math.floor(Math.random()*speakingBank.part2.length),p2=speakingBank.part2[p2Index];
 const p3=speakingBank.part3[p2.relatedPart3]||speakingBank.part3[0];
 const questions=[
  ...pick(p1.questions,Math.min(4,p1.questions.length)).map(q=>({part:1,topic:p1.title,q:q.q})),
  {part:2,topic:p2.title,q:p2.questions[0].q},
  ...pick(p3.questions,Math.min(4,p3.questions.length)).map(q=>({part:3,topic:p3.title,q:q.q})),
 ];
 state.mockSession={questions,answers:questions.map(()=>({text:'',blob:null,url:null,mime:''})),current:0,topics:{part1:p1.title,part2:p2.title,part3:p3.title}};
 state.mockFeedback=null;state.mockLocalResult=null;state.mockLocalError='';state.mockLocalProgress='';mockPersist();renderMock();
}

function mockAnswered(answer){return !!(answer.text.trim()||answer.blob||answer.audioPath)}
function mockSaveDraft(){const s=state.mockSession,field=$('#mockAnswer');if(s&&field){s.answers[s.current].text=field.value.slice(0,4000);mockPersist()}}
function mockMove(delta){
 const s=state.mockSession;if(!s)return;
 if(state.mockRecording){toast('Avval audio yozishni to‘xtating.');return}
 mockSaveDraft();
 if(delta>0&&!mockAnswered(s.answers[s.current])){toast('Savolga yozma yoki audio javob kiriting.');return}
 s.current=Math.max(0,Math.min(s.questions.length-1,s.current+delta));mockPersist();renderMock();
}
function mockStopRecording(){
 const active=state.mockRecording;if(active&&active.recorder.state!=='inactive')active.recorder.stop();
}
async function mockUploadAudio(answer){
 if(!answer.blob||answer.uploading||!window.VocabCloud?.enabled)return;
 const blob=answer.blob;
 answer.uploading=true;answer.audioError='';
 try{const path=await window.VocabCloud.uploadAudio(blob);if(answer.blob===blob){answer.audioPath=path;mockPersist();toast('Audio hisobingizga saqlandi.')}}
 catch(error){answer.audioError=error.message||'Audio saqlanmadi.';toast(answer.audioError)}
 finally{answer.uploading=false;if(answer.blob!==blob&&!answer.audioPath)mockUploadAudio(answer);if(state.view==='speakingmock')renderMock()}
}
async function mockLoadAudio(answer){
 if(!answer.audioPath||answer.blob||answer.loading||!window.VocabCloud?.enabled)return;
 const path=answer.audioPath;
 answer.loading=true;answer.audioError='';
 try{const blob=await window.VocabCloud.downloadAudio(path);if(answer.audioPath===path&&!answer.blob){answer.blob=blob;answer.url=URL.createObjectURL(blob)}}
 catch(error){answer.audioError=error.message||'Audio yuklanmadi.'}
 finally{answer.loading=false;if(state.view==='speakingmock')renderMock()}
}
async function mockRecord(){
 if(state.mockRecording){mockStopRecording();return}
 if(!state.mockSession||!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined'){toast('Bu brauzerda mikrofon orqali yozib bo‘lmadi. Yozma javobdan foydalaning.');return}
 mockSaveDraft();
 let stream;
 try{
  stream=await navigator.mediaDevices.getUserMedia({audio:true});
  if(state.view!=='speakingmock'||!state.mockSession){stream.getTracks().forEach(t=>t.stop());return}
  const mime=['audio/webm;codecs=opus','audio/webm','audio/ogg;codecs=opus','audio/mp4'].find(type=>MediaRecorder.isTypeSupported?.(type));
  const recorder=new MediaRecorder(stream,{...(mime?{mimeType:mime}:{}),audioBitsPerSecond:48_000});
  const session=state.mockSession,index=session.current,chunks=[];
  recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};
  recorder.onstop=()=>{
   stream.getTracks().forEach(t=>t.stop());
   const blob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'});
   if(state.mockRecording?.recorder===recorder)state.mockRecording=null;
   const answer=session.answers[index];
   if(answer&&blob.size){
    if(blob.size>3_000_000)toast('Audio hajmi 3 MB dan oshdi. Qisqaroq yozib ko‘ring.');
    else{
     if(answer.url)URL.revokeObjectURL(answer.url);
     answer.blob=blob;answer.mime=blob.type.split(';')[0];answer.url=URL.createObjectURL(blob);answer.transcript='';answer.audioPath=null;answer.audioError='';mockPersist();mockUploadAudio(answer);
    }
   }
   if(state.view==='speakingmock')renderMock();
  };
  recorder.start();
  state.mockRecording={recorder,index};
  renderMock();
 }catch{
  stream?.getTracks().forEach(t=>t.stop());
  toast('Mikrofonga ruxsat berilmadi. Yozma javobdan foydalaning.');
 }
}
function mockFinish(){
 const s=state.mockSession;if(!s)return;
 if(state.mockRecording){toast('Avval audio yozishni to‘xtating.');return}
 mockSaveDraft();
 if(s.answers.some(x=>!mockAnswered(x))){toast('Barcha savollarga javob bering.');return}
 if(window.VocabCloud?.enabled&&s.answers.some(x=>x.blob&&!x.audioPath)){toast('Audio hali hisobga saqlanmadi. Qayta yuborib ko‘ring.');return}
 state.mockFeedback={local:true};
 const archived={id:`sm-${Date.now()}`,date:new Date().toISOString().slice(0,10),at:new Date().toISOString(),questions:s.questions.map((q,i)=>({part:q.part,topic:q.topic,q:q.q,answer:s.answers[i]?.text||s.answers[i]?.transcript||'',audioPath:s.answers[i]?.audioPath||''}))};
 mockArchive.unshift(archived);mockArchive=mockArchive.slice(0,100);try{localStorage.setItem(storageKey('vivid-ielts-mock-archive-v1'),JSON.stringify(mockArchive))}catch{};recordUnifiedHistory('Speaking Mock','Speaking mock tugadi',`${s.questions.length} ta savol`,{mockId:archived.id});mockPersist();renderMock();
}
async function mockAnalyze(){
 const s=state.mockSession;
 if(!s||state.mockLocalBusy)return;
 state.mockLocalBusy=true;state.mockLocalResult=null;state.mockLocalError='';
 state.mockLocalProgress='Qurilmangizdagi tahlil tayyorlanmoqda…';renderMockFeedback();
 let lastRender=0;
 const progress=message=>{
  if(state.mockSession!==s)return;
  state.mockLocalProgress=message;
  if(Date.now()-lastRender>450&&state.view==='speakingmock'){renderMockFeedback();lastRender=Date.now()}
 };
 try{
  for(const answer of s.answers)if(answer.audioPath&&!answer.blob&&!answer.text.trim())await mockLoadAudio(answer);
  if(s.answers.some(answer=>answer.audioPath&&!answer.blob&&!answer.text.trim()))throw Error('Audio yuklanmadi. Sahifani yangilab qayta urinib ko‘ring.');
  const {evaluateLocal}=await import('./mock-local.mjs');
  const result=await evaluateLocal(s.questions,s.answers,progress);
  if(state.mockSession===s){state.mockLocalResult=result;mockPersist()}
 }catch(error){
  if(state.mockSession===s)state.mockLocalError=error?.message||'Mahalliy tahlil ishlamadi. Sahifani yangilab qayta urinib ko‘ring.';
 }finally{
  if(state.mockSession===s){state.mockLocalBusy=false;state.mockLocalProgress='';if(state.view==='speakingmock')renderMockFeedback()}
 }
}
function renderMockFeedback(){
 const s=state.mockSession;
 let html=heading('Speaking Mock · javoblar','Mock tugadi. Javoblaringizni shu yerda ko‘rib chiqing.',s.questions.length+' / '+s.questions.length);
 html+='<div class="page-back-row"><button type="button" class="page-back" data-action="mock-revise" '+(state.mockLocalBusy?'disabled':'')+'>← Javoblarga qaytish</button><button type="button" class="primary-btn" data-action="mock-new" '+(state.mockLocalBusy?'disabled':'')+'>Yangi mock ↻</button></div>';
 html+='<section class="panel mock-summary"><strong>Kalitsiz mashq tahlili</strong><p>Yozma javob va audio shu qurilmada tahlil qilinadi. Bir savolga matn ham, audio ham kiritilsa, yozma javob asos olinadi. Birinchi safar katta model fayllari internetdan yuklanadi; javobingiz va ovozingiz AI xizmatiga yuborilmaydi. Bu rasmiy IELTS bahosi emas.</p><button type="button" class="primary-btn" data-action="mock-analyze" '+(state.mockLocalBusy?'disabled':'')+'>'+(state.mockLocalBusy?'Tahlil qilinmoqda…':'Qurilmada tahlil qilish →')+'</button>'+(state.mockLocalProgress?'<p class="mock-progress" role="status">'+esc(state.mockLocalProgress)+'</p>':'')+(state.mockLocalError?'<p class="mock-error" role="alert">'+esc(state.mockLocalError)+'</p>':'')+'</section>';
 if(state.mockLocalResult){
  const r=state.mockLocalResult;
  html+='<div class="mock-criteria">'+[['lexical','Lexical resource'],['grammar','Grammatical range & accuracy']].map(([key,label])=>{const c=r[key]||{};return '<section class="panel mock-criterion"><div><h2>'+label+'</h2><b>'+(c.score==null?'Yetarli dalil yo‘q':esc(c.score)+' / 9*')+'</b></div>'+(c.quote?'<p><strong>Javobdan:</strong> “'+esc(c.quote)+'”</p>':'')+(c.reason?'<p>'+esc(c.reason)+'</p>':'')+(c.tip?'<small>Keyingi qadam: '+esc(c.tip)+'</small>':'')+'</section>'}).join('')+'<section class="panel mock-criterion"><div><h2>Fluency & coherence</h2><b>Band yo‘q</b></div><p>'+esc(r.coherence||'Matndagi fikr bog‘lanishini kuzatishingiz mumkin. Og‘zaki ravonlikka ishonchli ball uchun audio tahlili yetarli emas.')+'</p></section><section class="panel mock-criterion"><div><h2>Pronunciation</h2><b>Band yo‘q</b></div><p>Ovozdan talaffuz, urg‘u va intonatsiyaga ishonchli band chiqarmaymiz.</p></section></div>';
  html+='<section class="panel mock-detail"><p class="mock-limit">* So‘z boyligi va grammatika ballari faqat mashq uchun taxmin. Umumiy Speaking band hisoblanmaydi.'+(r.tooShort?' Inglizcha javoblar qisqa bo‘lgani uchun ball berilmadi.':'')+'</p></section>';
 }
 html+='<section class="panel mock-detail"><h2>Savollar va javoblar</h2>'+s.questions.map((q,i)=>'<div class="mock-fix"><small>PART '+q.part+' · '+esc(q.topic)+'</small><p><strong>'+esc(q.q)+'</strong></p>'+(s.answers[i].text?'<p>'+esc(s.answers[i].text)+'</p>':'')+(s.answers[i].transcript?'<p class="mock-transcript"><b>Audio matni (avtomatik):</b> '+esc(s.answers[i].transcript)+'</p>':'')+(s.answers[i].url?'<audio controls preload="metadata" src="'+esc(s.answers[i].url)+'" aria-label="'+(i+1)+'-savol javobi"></audio>':'')+'</div>').join('')+'</section>';
 root.innerHTML=html;
}
function renderMock(){
 if(!speakingBank){
  root.innerHTML=heading('Speaking Mock','Savollar yuklanmoqda…')+'<div class="loading"><span class="spinner"></span> Yuklanmoqda…</div>';
  loadSpeakingBank();return;
 }
 mockRestore();
 const s=state.mockSession;
 if(s&&window.VocabCloud?.enabled)for(const answer of s.answers)if(answer.audioPath&&!answer.blob&&!answer.loading&&!answer.audioError)mockLoadAudio(answer);
 if(!s){
  root.innerHTML=heading('Speaking Mock','Part 1 mavzusi, Part 2 cue card va unga bog‘liq Part 3 savollari tasodifiy tanlanadi.')+
   '<div class="page-back-row"><button type="button" class="page-back" data-action="back-one">← Ortga</button></div>'+
   '<section class="panel mock-start"><div class="mock-path"><span>PART 1<br><b>Bir mavzu</b></span><span>PART 2<br><b>Cue card</b></span><span>PART 3<br><b>Bog‘liq savollar</b></span></div><h2>O‘z tezligingizda javob bering</h2><p>Taymer yo‘q. Matn yozing yoki audio yozib oling. Yakunda qurilmangizning o‘zida so‘z boyligi va grammatikaga taxminiy tahlil olishingiz mumkin. Talaffuz va umumiy Speaking band chiqarilmaydi. '+(window.VocabCloud?.enabled?'Javoblar va audio hisobingizga saqlanadi.':'Bulutga ulanish yo‘q: audio sahifa yopilguncha qoladi.')+'</p><div class="mock-launch"><button type="button" class="primary-btn" data-action="mock-new">Mockni boshlash →</button></div></section>';
  return;
 }
 if(state.mockFeedback){renderMockFeedback();return}
 const q=s.questions[s.current],answer=s.answers[s.current],part=q.part,filled=s.answers.filter(mockAnswered).length;
 let html=heading('Speaking Mock','Taymer yo‘q — javobingiz tayyor bo‘lganda keyingi savolga o‘ting.',(s.current+1)+' / '+s.questions.length);
 html+='<div class="page-back-row"><button type="button" class="page-back" data-action="back-one">← Mockdan chiqish</button><span class="speaking-count">'+filled+' / '+s.questions.length+' javob</span></div>';
 html+='<div class="mock-stepper">'+[1,2,3].map(n=>'<span class="'+(n===part?'active':'')+'">Part '+n+'</span>').join('')+'</div>';
 html+='<section class="panel mock-question"><div class="mock-topic">PART '+part+' · '+esc(q.topic)+'</div><h2>'+esc(q.q)+'</h2>'+(part===2?'<p class="note">Bitta mavzu haqida izchil gapiring. Tayyor bo‘lgach javobni yozib oling.</p>':'')+'</section>';
 html+='<section class="panel mock-answer"><label for="mockAnswer">Javobingiz (yozma)</label><textarea id="mockAnswer" maxlength="4000" placeholder="Inglizcha javobingizni yozing...">'+esc(answer.text)+'</textarea><div class="mock-audio-row"><button type="button" class="'+(state.mockRecording?'mock-recording':'secondary-btn')+'" data-action="mock-record">'+(state.mockRecording?'■ Yozishni to‘xtatish':'🎙 Mikrofon orqali javob')+'</button>'+(answer.url?'<audio controls preload="metadata" src="'+esc(answer.url)+'" aria-label="Yozilgan javob"></audio>':'')+(answer.uploading?'<span>Bulutga saqlanmoqda…</span>':answer.audioPath?'<span>Hisobga saqlandi ✓</span>':answer.loading?'<span>Audio yuklanmoqda…</span>':answer.blob&&window.VocabCloud?.enabled?'<button type="button" class="secondary-btn" data-action="mock-upload">Bulutga qayta saqlash</button>':'')+'</div>'+(answer.audioError?'<p class="mock-error">'+esc(answer.audioError)+'</p>':'')+'<small>Taymer va avtomatik to‘xtash yo‘q. Hisobga kirgan bo‘lsangiz, audio bulutga saqlanadi.</small></section>';
 html+='<div class="mock-controls"><button type="button" class="secondary-btn" data-action="mock-prev" '+(s.current===0?'disabled':'')+'>← Oldingi savol</button>'+(s.current===s.questions.length-1?'<button type="button" class="primary-btn" data-action="mock-finish">Javoblarni ko‘rish →</button>':'<button type="button" class="primary-btn" data-action="mock-next">Keyingi savol →</button>')+'</div>';
 root.innerHTML=html;
}
function mockHandleAction(action){
 if(action==='mock-new'){if(state.mockLocalBusy)return true;if(state.mockRecording)mockStopRecording();mockNew();return true}
 if(action==='mock-prev'){mockMove(-1);return true}
 if(action==='mock-next'){mockMove(1);return true}
 if(action==='mock-record'){mockRecord();return true}
 if(action==='mock-upload'){const a=state.mockSession?.answers[state.mockSession.current];if(a)mockUploadAudio(a);return true}
 if(action==='mock-finish'){mockFinish();return true}
 if(action==='mock-revise'){if(state.mockLocalBusy)return true;state.mockFeedback=null;state.mockLocalResult=null;mockPersist();renderMock();return true}
 if(action==='mock-analyze'){mockAnalyze();return true}
 return false;
}
