async function lbLoadData(){if(lbData||lbDataLoading)return;lbDataLoading=true;try{const r=await fetch('listening-data.json',{headers:{accept:'application/json'}});if(!r.ok)throw Error('Listening data unavailable');const d=await r.json();if(!d||!Array.isArray(d.lessons)||d.lessons.length!==60)throw Error('Listening plan invalid');lbData=d}catch(e){lbData={error:e?.message||'Listening plan yuklanmadi.',lessons:[]}}finally{lbDataLoading=false;if(state.view==='listeningboost')renderListeningBoost()}}
function lbLesson(id=lbLessonId){return lbData?.lessons?.find(x=>x.id===id)||null}
function lbLessonsForDay(day=lbDay){return (lbData?.lessons||[]).filter(x=>x.day===day).sort((a,b)=>a.kind==='short'?-1:1)}
function lbLevel(lesson){return lesson?.level||window.ListeningEngine?.levelForDay?.(lesson?.day)||((lesson?.day||1)<=10?'B2':(lesson?.day||1)<=20?'C1':'C2')}
function lbState(id){const all=listeningBoostProgress.lessons||(listeningBoostProgress.lessons={});const s=all[id]||(all[id]={answers:{},scores:{},videoUrl:'',content:null,completedAt:''});if(!s.answers||typeof s.answers!=='object')s.answers={};if(!s.scores||typeof s.scores!=='object')s.scores={};return s}
function lbLegacyTopic(sentence){const words=String(sentence||'').toLowerCase().replace(/[^a-z0-9' ]+/g,' ').split(/\s+/).filter(w=>w.length>4&&!['about','there','their','which','while','these','those','would','could','should','because','audio','speaker'].includes(w));return (words.slice(0,2).join(' ')||'this point')}
function lbMigrateLegacyContent(s,lesson,engine){const c=s.content;if(!c||c.engineVersion===engine)return false;if(lesson.starterContent&&lesson.starterContent.engineVersion===engine){s.content=JSON.parse(JSON.stringify(lesson.starterContent));s.answers={};s.scores={};s.completedAt='';delete s.needsTranscriptRefresh;return true}if(window.ListeningEngine?.upgradeContent){try{s.content=window.ListeningEngine.upgradeContent(c,lesson.counts,lesson.id,lbLevel(lesson));delete s.answers?.notes;delete s.scores?.notes;s.needsTranscriptRefresh=true;delete s.revealed;return true}catch{}}c.engineVersion=engine;c.level=lbLevel(lesson);delete c.notes;delete s.answers?.notes;delete s.scores?.notes;s.needsTranscriptRefresh=true;return true}
function lbPrepareLesson(lesson){const s=lbState(lesson.id),engine=window.ListeningEngine?.ENGINE_VERSION||'4.0';let changed=false;if(s.content&&s.content.engineVersion!==engine)changed=lbMigrateLegacyContent(s,lesson,engine)||changed;if(!s.content&&lesson.starterContent&&lesson.starterContent.engineVersion===engine){try{s.content=JSON.parse(JSON.stringify(lesson.starterContent));s.answers={};s.scores={};s.completedAt='';delete s.needsTranscriptRefresh;changed=true}catch{}}if(changed)lbSave();return s}
function lbItems(lesson,mode){return lbPrepareLesson(lesson).content?.[mode]||[]}
