function lbLessonProgress(lesson){const s=lbPrepareLesson(lesson),c=s.content;if(!c)return {done:0,total:lesson.total,pct:0,ready:false};let done=0;for(const mode of Object.keys(lbModeMeta)){const items=c[mode]||[],a=s.answers[mode]||{};done+=items.filter(x=>String(a[x.id]??'').trim()).length}const total=lesson.total,pct=Math.min(100,Math.round(100*done/Math.max(1,total)));return {done,total,pct,ready:true}}
function lbDayProgress(day){const lessons=lbLessonsForDay(day);const p=lessons.map(lbLessonProgress),done=p.reduce((a,x)=>a+x.done,0),total=p.reduce((a,x)=>a+x.total,0);return {done,total,pct:total?Math.round(100*done/total):0,complete:total>0&&done>=total}}
