function lbAudioPlayer(lesson){const src=window.ListeningEngine?.playerEmbedUrl(lbVideoUrl(lesson),location.origin)||'';return `<section class="lb-focus-player"><div class="lb-focus-head"><div><span class="lb-chip">🎧 AUDIO FOCUS</span>${lbLevelChip(lesson)}<h3>Video yashirilgan · transcript yopiq</h3><p>Faqat audioni eshiting va savollarga javob bering. Video tasviri va transcript mashq vaqtida ko‘rsatilmaydi.</p></div><span id="lbAudioTime" class="lb-audio-time">0:00</span></div>${src?`<iframe id="lbAudioFrame" class="lb-yt-audio-host" src="${esc(src)}" title="Listening audio source" allow="autoplay; encrypted-media" referrerpolicy="strict-origin-when-cross-origin" tabindex="-1" aria-hidden="true"></iframe>`:'<div class="lb-warning">YouTube audio manbasi topilmadi.</div>'}<div class="lb-audio-controls"><button type="button" class="lb-primary" data-action="lb-audio-play">▶ Play</button><button type="button" class="lb-secondary" data-action="lb-audio-pause">Ⅱ Pause</button><button type="button" class="lb-secondary" data-action="lb-audio-back">↶ 5s</button><button type="button" class="lb-secondary" data-action="lb-audio-forward">5s ↷</button><button type="button" class="lb-secondary" data-action="lb-audio-restart">↺ Boshidan</button></div><div class="lb-focus-lock">🔒 Transcript va javoblar tekshirishdan oldin ko‘rsatilmaydi.</div></section>`}
