window.openWritingGames=(cards,label)=>{if(!Array.isArray(cards)||!cards.length)return;writingGameWordsById=new Map();const items=cards.map((c,i)=>({id:c.id||`writing:${label}:${i}`,w:c.term||c.w||'',u:c.uz||c.u||'',d:'IELTS Writing collocation',e:c.example||c.e||'',p:'',t:`Writing · ${label}`,s:true}));for(const w of items)writingGameWordsById.set(w.id,w);pushPage('writingboost');state.packContext={section:`writing:${label}`,packIndex:0,ids:items.map(x=>x.id),number:1,label,origin:'writing'};state.view='packgames';render();scrollPageTop()};
